  final fb.BufferContext _bc;
  final int _bcOffset;

  ///  Possibility of collision, 0 to 1.
  double get POSSIBILITY_COLLISION => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 4, 0.0);
  double get possibilityCollision => POSSIBILITY_COLLISION;
  ///  Necessity of collision, 1 - possibility of no collision.
  double get NECESSITY_COLLISION => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 6, 0.0);
  double get necessityCollision => NECESSITY_COLLISION;
  ///  Necessity of no collision, 1 - POSSIBILITY_COLLISION.
  double get NECESSITY_NO_COLLISION => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 8, 0.0);
  double get necessityNoCollision => NECESSITY_NO_COLLISION;
  ///  Smallest and largest miss distance over all pairs, m.
  double get MIN_MISS_M => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 10, 0.0);
  double get minMissM => MIN_MISS_M;
  double get MAX_MISS_M => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 12, 0.0);
